  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/string_utils.py": "\"\"\"Module for string utility functions.\"\"\"\n\ndef capitalize_words(s):\n    \"\"\"Capitalize each word in the input string.\n\n    Args:\n        s (str): Input string to capitalize.\n\n    Returns:\n        str: String with each word capitalized.\n    \n    Raises:\n        AttributeError: If input is not a string.\n    \"\"\"\n    if not isinstance(s, str):\n        raise AttributeError(\"Input must be a string\")\n    return \" \".join(word.capitalize() for word in s.split())\n\ndef reverse_string(s):\n    \"\"\"Reverse the input string.\n\n    Args:\n        s (str): Input string to reverse.\n\n    Returns:\n        str: Reversed string.\n    \n    Raises:\n        TypeError: If input is not a string.\n    \"\"\"\n    if not isinstance(s, str):\n        raise TypeError(\"Input must be a string\")\n    return s[::-1]\n\ndef json_example():\n    \"\"\"Return a JSON string example.\n\n    Returns:\n        str: JSON string example.\n    \"\"\"\n    return '{\"name\": \"John\", \"age\": 30}'",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/calculator.py": "\"\"\"Module for basic arithmetic operations.\"\"\"\n\ndef add(a, b):\n    \"\"\"Add two numbers.\n\n    Args:\n        a (int/float): First number.\n        b (int/float): Second number.\n\n    Returns:\n        int/float: Sum of a and b.\n    \"\"\"\n    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):\n        raise TypeError(\"Inputs must be numeric\")\n    return a + b\n\ndef subtract(a, b):\n    \"\"\"Subtract two numbers.\n\n    Args:\n        a (int/float): First number.\n        b (int/float): Second number.\n\n    Returns:\n        int/float: Result of a minus b.\n    \"\"\"\n    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):\n        raise TypeError(\"Inputs must be numeric\")\n    return a - b\n\ndef multiply(a, b):\n    \"\"\"Multiply two numbers.\n\n    Args:\n        a (int/float): First number.\n        b (int/float): Second number.\n\n    Returns:\n        int/float: Product of a and b.\n    \"\"\"\n    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):\n        raise TypeError(\"Inputs must be numeric\")\n    return a * b\n\ndef divide(a, b):\n    \"\"\"Divide two numbers.\n\n    Args:\n        a (int/float): Numerator.\n        b (int/float): Denominator.\n\n    Returns:\n        int/float/str: Result of division or error message if division by zero.\n    \n    Raises:\n        TypeError: If inputs are not numeric.\n    \"\"\"\n    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):\n        raise TypeError(\"Inputs must be numeric\")\n    if b == 0:\n        return \"Cannot divide by zero\"\n    return a / b",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/tests/test_string_utils.py": "import pytest\nfrom sandbox.string_utils import capitalize_words, reverse_string, json_example\n\n\ndef test_capitalize_words_basic():\n    assert capitalize_words(\"hello world\") == \"Hello World\"\n    assert capitalize_words(\"python testing\") == \"Python Testing\"\n\n\ndef test_capitalize_words_empty_string():\n    assert capitalize_words(\"\") == \"\"\n\n\ndef test_capitalize_words_single_word():\n    assert capitalize_words(\"hello\") == \"Hello\"\n\n\ndef test_capitalize_words_multiple_spaces():\n    assert capitalize_words(\"  hello   world  \") == \"Hello World\"\n\n\ndef test_capitalize_words_non_string_input():\n    with pytest.raises(AttributeError):\n        capitalize_words(123)\n\n\ndef test_reverse_string_basic():\n    assert reverse_string(\"hello\") == \"olleh\"\n    assert reverse_string(\"world\") == \"dlrow\"\n\n\ndef test_reverse_string_empty_string():\n    assert reverse_string(\"\") == \"\"\n\n\ndef test_reverse_string_single_char():\n    assert reverse_string(\"a\") == \"a\"\n\n\ndef test_reverse_string_non_string_input():\n    with pytest.raises(TypeError):\n        reverse_string(123)\n\n\ndef test_json_example():\n    result = json_example()\n    assert result == '{\"name\": \"John\", \"age\": 30}'\n    assert isinstance(result, str)\n\n\ndef test_json_example_parsing():\n    import json\n    result = json_example()\n    parsed = json.loads(result)\n    assert parsed == {\"name\": \"John\", \"age\": 30}",
  "/Users/hf/Desktop/refactoring-swarm-template/sandbox/tests/test_calculator.py": "import pytest\nfrom sandbox.calculator import add, subtract, multiply, divide\n\n\ndef test_add_integers():\n    assert add(2, 3) == 5\n    assert add(-1, 1) == 0\n    assert add(0, 0) == 0\n\n\ndef test_add_floats():\n    assert add(1.5, 2.5) == 4.0\n    assert add(-1.1, 1.1) == 0.0\n\n\ndef test_add_mixed_types():\n    assert add(2, 3.0) == 5.0\n    assert add(1.5, 2) == 3.5\n\n\ndef test_subtract_integers():\n    assert subtract(5, 3) == 2\n    assert subtract(3, 5) == -2\n    assert subtract(0, 0) == 0\n\n\ndef test_subtract_floats():\n    assert subtract(5.5, 2.5) == 3.0\n    assert subtract(2.5, 5.5) == -3.0\n\n\ndef test_subtract_mixed_types():\n    assert subtract(5, 2.5) == 2.5\n    assert subtract(5.5, 2) == 3.5\n\n\ndef test_multiply_integers():\n    assert multiply(2, 3) == 6\n    assert multiply(-1, 1) == -1\n    assert multiply(0, 5) == 0\n\n\ndef test_multiply_floats():\n    assert multiply(1.5, 2.0) == 3.0\n    assert multiply(-1.5, 2.0) == -3.0\n\n\ndef test_multiply_mixed_types():\n    assert multiply(2, 3.0) == 6.0\n    assert multiply(1.5, 2) == 3.0\n\n\ndef test_divide_normal():\n    assert divide(6, 3) == 2\n    assert divide(5, 2) == 2.5\n    assert divide(5.0, 2) == 2.5\n\n\ndef test_divide_by_zero():\n    assert divide(5, 0) == \"Cannot divide by zero\"\n    assert divide(0, 0) == \"Cannot divide by zero\"\n\n\ndef test_divide_non_numeric_input():\n    with pytest.raises(TypeError):\n        divide(\"5\", 2)\n    with pytest.raises(TypeError):\n        divide(5, \"2\")\n\n\ndef test_divide_boundary_values():\n    assert divide(1, 1e-10) == 1e10\n    assert divide(1e-10, 1) == 1e-10"
